function projectChoice(c:Course,raw:string|undefined):Course{
 if(!raw)return c;
 const [l,t]=raw.split(':');
 const norm=t?(l||sectionsOfKind(c,'LEC')[0]?.sectionCode||'')+':'+t:l;
 return withSection(c,norm);
}
