   {lecs.length>1&&<div className="registered-section-picker">{tr('班次','Section')}<Select aria-label={tr(`更换 ${rc.id} 班次`,`Change ${rc.id} section`)} value={sectionChoices[rc.id]?.split(':')[0]??lecs[0].sectionCode} onChange={changeSection}>{lecs.map(s=><option key={s.sectionCode} value={s.sectionCode} disabled={s.availableSeats<=0&&s.sectionCode!==(sectionChoices[rc.id]?.split(':')[0]??'')}>{s.sectionCode} · {s.availableSeats} {tr('余位','seats')}</option>)}</Select></div>}
