function SessionPickers({course,sectionChoices,setSectionChoices,tr}:{course:Course;sectionChoices:Record<string,string>;setSectionChoices:(f:(sc:Record<string,string>)=>Record<string,string>)=>void;tr:(z:string,e:string)=>string}){
 const lec=sectionsOfKind(course,'LEC'), tut=sectionsOfKind(course,'TUT');
 const cur=sectionChoices[course.id]??'';
 const [lecCode,tutCode]=cur.split(':');
 if(lec.length<2&&tut.length===0)return null;
 const setLec=(v:string)=>setSectionChoices(sc=>({...sc,[course.id]:tutCode?`${v}:${tutCode}`:v}));
 const setTut=(v:string)=>setSectionChoices(sc=>({...sc,[course.id]:v?`${lecCode||lec[0]?.sectionCode||''}:${v}`:(lecCode||'')}));
 return <div className="session-pickers">
  {lec.length>=2&&<div className="session-picker-field">{tr('讲义班次','Lecture section')}<Select aria-label={tr(`${course.id} 讲义班次`,`${course.id} lecture section`)} value={lecCode??lec[0].sectionCode} onChange={setLec}>{lec.map(s=><option key={s.sectionCode} value={s.sectionCode}>{s.sectionCode} · {s.availableSeats} {tr('余位','seats')}</option>)}</Select></div>}
  {tut.length>0&&<div className="session-picker-field">{tr('习题班次','Tutorial section')}<Select aria-label={tr(`${course.id} 习题班次`,`${course.id} tutorial section`)} value={tutCode??''} onChange={setTut}><option value="">{tr('不参加','None')}</option>{tut.map(s=><option key={s.sectionCode} value={s.sectionCode}>{s.sectionCode} · {s.availableSeats} {tr('余位','seats')}</option>)}</Select></div>}
 </div>;
}

function AcademicProgress({tr,enrolledCourses,plannedList,persona}:{tr:(z:string,e:string)=>string;enrolledCourses:Course[];plannedList:Course[];persona:import('@/lib/persona').Persona}){
 const catMap:Record<string,string>={'专业必修':'major_required','专业选修':'major_elective','通识教育':'general_education','自由选修':'free_elective'};
 const creditsOf=(cs:Course[])=>cs.reduce((s,c)=>s+c.credits,0);
 const byCat=(cs:Course[])=>{const out:Record<string,number>={};for(const c of cs){const k=catMap[c.category]??'free_elective';out[k]=(out[k]??0)+c.credits}return out};
 const enrolledTotal=creditsOf(enrolledCourses),enrolledByCat=byCat(enrolledCourses),plannedByCat=byCat(plannedList),plannedTotal=creditsOf(plannedList);
 const prog=(()=>{
  const reqs=DEGREE_REQUIREMENTS.filter(r=>r.major===persona.major);
  const completedCredits=persona.completed.reduce((s,c)=>s+c.credits,0);
  // completed per category: only courses present in the catalog can be attributed; others count toward free elective
  const catOf:Record<string,string>={};
  for(const c of courses)catOf[c.id]=catMap[c.category]??'free_elective';
  const byCatDone:Record<string,number>={};
  for(const cc of persona.completed){const k=catOf[cc.courseCode]??'free_elective';byCatDone[k]=(byCatDone[k]??0)+cc.credits}
  return {
   completedCredits,
   requirements:reqs.map(r=>({category:r.category,labelZh:r.labelZh,requiredCredits:r.requiredCredits,completed:r.category==='total'?completedCredits:(byCatDone[r.category]??0)})),
  };
 })();
 const catLabel:Record<string,string>={major_required:tr('专业必修','Major Required'),major_elective:tr('专业选修','Major Elective'),general_education:tr('通识教育','General Education'),free_elective:tr('自由选修','Free Elective')};
 return <div className="summary-grid">
  <Summary icon={<GraduationCap size={20}/>} title={tr('已修学分','Completed')} value={String(prog.completedCredits)} suffix={`/ ${prog.requirements?.find((r:any)=>r.category==='total')?.requiredCredits??120}`} foot={tr(`已注册 ${enrolledTotal} · 计划中 ${plannedTotal} 学分`,`${enrolledTotal} enrolled · ${plannedTotal} planned`)}/>
  {(prog.requirements??[]).filter((v:any)=>v.category!=='total').map((v:any)=>{
   const planned=plannedByCat[v.category]??0;
   const enrolledHere=enrolledByCat[v.category]??0;
   const plannedTop=v.category==='total'?0:planned;
   return <Summary key={v.category} icon={<BookOpen size={20}/>} title={catLabel[v.category]??v.labelZh} value={String(v.completed)} suffix={`/ ${v.requiredCredits}`} foot={tr(`已注册 ${enrolledHere} · 计划 ${planned} · 缺口 ${Math.max(0,v.requiredCredits-v.completed-enrolledHere-planned)}`,`enrolled ${v.enrolled} · planned ${planned} · gap ${Math.max(0,v.requiredCredits-v.completed-enrolledHere-planned)}`)}/>})}
 </div>;
}
function Summary({icon,title,value,suffix,foot,good=false,warning=false}:{icon:React.ReactNode;title:string;value:string;suffix?:string;foot:React.ReactNode;good?:boolean;warning?:boolean}){return <Localized><section className="card summary-card"><div className="summary-title"><span>{title}</span>{icon}</div><div className={`summary-value ${good?'good':warning?'warning-value':''}`}>{good&&<Check size={23}/>} {warning&&<TriangleAlert size={21}/>}<strong>{value}</strong>{suffix&&<span>{suffix}</span>}</div><div className="summary-foot">{foot}</div></section></Localized>}
function CourseCard({course:c,added,candidateAdded,plans,onDetail,onAddCandidate,onAddPlan,onRemove,clash}:{course:Course;added:boolean;candidateAdded:boolean;plans:Record<string,Plan>;onDetail:()=>void;onAddCandidate:()=>void;onAddPlan:(target:string)=>void;onRemove:()=>void;clash?:Course}){
 const en=useLanguage()==='en';
 const tr=(z:string,e:string)=>en?e:z;
 return <Localized><article className="card course-card">
  <div className="course-card-top"><span className={`course-code ${c.tone}`}>{c.id}</span><span className="muted">需求 {c.demand}</span></div>
  <h2>{c.title}</h2><p className="course-english">{c.english}</p>
  <div className="course-meta"><span><UserRound size={15}/>{c.instructor}</span><span><Clock3 size={15}/>{c.days.map(d=>dayNames[d]).join(' / ')} {time(c.start)}–{time(c.end)}</span></div>
  <div className="course-seats"><span><b>{c.seats}</b> / {c.capacity} 可用名额</span><span title="为特定学生群体保留的名额。">预留 {c.quota} <Info size={12}/></span><span>候补 {c.wait}</span></div>
  <p className="muted">面向：计算机科学及相关专业本科生</p>
  <div className="detail-tags"><span className="tag">{c.category}</span><span className="tag">{c.eligible?'符合条件':'先修未满足'}</span><span className="tag">{c.workload}工作量</span></div>
  {c.eligible&&<p className="counts-inline"><Check size={13} aria-hidden="true"/>{tr(`计入${c.category}`,`Counts toward ${catEn[c.category]}`)}</p>}
  {clash&&!added&&<p className="conflict-hint"><TriangleAlert size={13} aria-hidden="true"/>{tr(`与 ${clash.id} 时间冲突`,`Time Conflict with ${clash.id}`)} · {slot(clash,en)}</p>}
  <div className="course-actions">
   <Button variant="default" data-tour={c.id==='CSC4130'?'course-detail':undefined} onClick={onDetail}>{tr('查看课程详情','View Course Details')}</Button>
   {added&&<><span className="added-pill" role="status">{tr('已加入 ✓','Added ✓')}</span><Button variant="default" onClick={onRemove}>{tr('移除','Remove')}</Button></>}
   <Button variant="primary" disabled={candidateAdded} onClick={onAddCandidate}>{candidateAdded?tr('已加入候选','Added to Candidates'):tr('加入候选课程','Add to Candidates')}</Button>
   <PlanPicker course={c} plans={plans} onAdd={onAddPlan}/>
  </div>
 </article></Localized>;
}





